/* 由 gen_audio.py 生成：每篇听力的音频与逐句时间轴 */
const AUDIO = {"lc1": {"src": "assets/audio/lc1.m4a", "dur": 166.7, "q": 94.26, "segs": [[0.0, 4.27, "W", "So, Mark, I heard you just finished a summer internship at a marketing firm."], [4.39, 5.45, "W", "How did it go?"], [5.92, 8.89, "M", "Honestly, it was nothing like what I expected."], [9.01, 18.29, "M", "I thought I'd be sitting in meetings and brainstorming campaign ideas, but for the first two weeks they had me cleaning up customer databases."], [18.76, 20.04, "W", "That sounds tedious."], [20.51, 22.04, "M", "It was, at first."], [22.16, 27.86, "M", "But then my supervisor explained that every campaign starts with knowing who you are talking to."], [27.98, 32.35, "M", "Once I understood why the data mattered, the work felt less pointless."], [32.82, 35.38, "W", "Did you eventually get to do anything creative?"], [35.85, 36.81, "M", "I did."], [36.93, 43.1, "M", "In the last month they let me draft social media posts for a small client, a local bakery."], [43.22, 50.6, "M", "Two of my posts actually went out, and one of them got more engagement than anything the client had posted before."], [51.07, 52.54, "W", "That must have felt great."], [53.01, 56.11, "M", "It did, but what I valued most was the feedback."], [56.23, 59.7, "M", "My supervisor went through every draft line by line."], [59.82, 62.79, "M", "She was tough, but she never made me feel stupid."], [63.26, 65.41, "W", "Would you go back if they offered you a job?"], [65.88, 67.27, "M", "I'd consider it."], [67.39, 73.64, "M", "The pay was low and the commute was awful, but I learned more in ten weeks than in a whole semester."], [73.76, 77.26, "M", "The one thing I'd want is a clearer path for promotion."], [77.38, 81.54, "M", "Right now most people there seem to stay in the same role for years."], [82.01, 85.93, "W", "So it's a question of long-term prospects rather than the work itself."], [86.4, 87.47, "M", "Exactly."], [87.59, 89.66, "M", "I liked the people and the work."], [89.78, 92.79, "M", "I'm just not sure it's where I want to be at thirty."], [94.26, 99.02, "Q", "Questions 1 to 4 are based on the conversation you have just heard."], [100.22, 105.06, "Q", "Question 1. What did Mark do during the first two weeks of his internship?"], [117.06, 121.37, "Q", "Question 2. Why did the work feel less pointless to Mark later on?"], [133.37, 137.46, "Q", "Question 3. What did Mark value most about the internship?"], [149.46, 154.73, "Q", "Question 4. What concerns Mark about accepting a job offer from the firm?"]]}, "lc2": {"src": "assets/audio/lc2.m4a", "dur": 167.4, "q": 97.55, "segs": [[0.0, 2.82, "M", "Linda, I was surprised to hear you're leaving the city."], [2.94, 4.64, "M", "You always said you'd never move."], [5.11, 5.86, "W", "I know."], [5.98, 13.19, "W", "But the rent went up again this year, and I realized I was spending over half my income just to live in a tiny apartment."], [13.66, 14.62, "M", "Where are you going?"], [15.09, 16.86, "W", "A town about two hours north."], [16.98, 23.23, "W", "My company lets us work remotely three days a week, so I only need to come in on Tuesdays and Thursdays."], [23.7, 26.65, "M", "Isn't the commute going to be exhausting on those days?"], [27.12, 31.19, "W", "It's long, but the train has good Wi-Fi, so I can work on the way."], [31.31, 36.86, "W", "I'll count those two hours as part of my working day, so I won't get home any later than I do now."], [36.98, 43.31, "W", "And on the other days I'll have a garden, a quiet street, and a house that costs less than my current rent."], [43.78, 45.21, "M", "What about your social life?"], [45.33, 46.65, "M", "Everyone you know is here."], [47.12, 49.9, "W", "That's the part I worry about most, to be honest."], [50.02, 54.56, "W", "I've already joined a hiking group there, and a friend from college lives nearby."], [54.68, 57.09, "W", "It will take time, but I think it's worth it."], [57.56, 60.27, "M", "And if it doesn't work out, you could always come back."], [60.74, 61.36, "W", "True."], [61.48, 64.98, "W", "I'm only renting the house for the first year, so I'm not locked in."], [65.1, 67.02, "W", "But I really hope I won't need to."], [67.49, 69.84, "M", "Do you think more people will do what you're doing?"], [70.31, 71.2, "W", "I think so."], [71.32, 78.23, "W", "The town has grown by almost ten percent in the last three years, and most of the newcomers are from the city, like me."], [78.35, 82.56, "W", "But that only continues as long as companies keep allowing remote work."], [82.68, 87.75, "W", "If they call everyone back to the office five days a week, the whole plan falls apart."], [88.22, 89.59, "M", "Well, I'll miss our lunches."], [89.71, 93.1, "M", "But I might come up for a weekend to see this garden of yours."], [93.57, 94.42, "W", "Please do."], [94.54, 96.08, "W", "I'll need help pulling weeds."], [97.55, 102.31, "Q", "Questions 1 to 4 are based on the conversation you have just heard."], [103.51, 107.39, "Q", "Question 1. Why has Linda decided to leave the city?"], [119.39, 122.72, "Q", "Question 2. How will Linda handle the long commute?"], [134.72, 138.03, "Q", "Question 3. What does Linda worry about most?"], [150.03, 155.44, "Q", "Question 4. What does Linda think will determine whether others follow her example?"]]}, "lp1": {"src": "assets/audio/lp1.m4a", "dur": 144.3, "q": 90.3, "segs": [[0.0, 6.42, "", "Over the past decade, beekeeping has quietly spread from the countryside into the hearts of major cities."], [6.64, 18.5, "", "Rooftops in London, Paris and Tokyo now host thousands of hives, and city councils often encourage the trend as a way to support pollinators and connect residents with nature."], [18.72, 22.33, "", "At first glance, cities seem like an unlikely home for bees."], [22.55, 27.18, "", "Yet studies have found that urban bees can be healthier than their rural cousins."], [27.4, 28.95, "", "The reason is diversity."], [29.17, 36.09, "", "In farmland, bees often face vast fields of a single crop, which blooms for a few weeks and then offers nothing."], [36.31, 42.73, "", "In cities, parks, gardens and street trees provide a mix of flowers from early spring to late autumn."], [42.95, 47.43, "", "Urban areas also use far fewer pesticides than commercial farms."], [47.65, 52.36, "", "However, researchers are now warning that enthusiasm may have gone too far."], [52.58, 59.2, "", "In some districts of London, the number of hives has grown so fast that there is not enough food to go around."], [59.42, 66.41, "", "Honeybees, which are essentially farm animals, compete with wild bees and other insects for the same flowers."], [66.63, 72.29, "", "When hives are too dense, wild species, many of which are already in decline, lose out."], [72.51, 75.71, "", "The scientists are not asking cities to ban beekeeping."], [75.93, 82.31, "", "Instead, they suggest that anyone who wants to help pollinators should plant flowers before buying a hive."], [82.53, 88.78, "", "A balcony full of lavender, they say, does more good than another box of honeybees on a crowded roof."], [90.3, 94.71, "Q", "Questions 1 to 3 are based on the passage you have just heard."], [95.91, 101.05, "Q", "Question 1. Why can city bees be healthier than those in the countryside?"], [113.05, 117.09, "Q", "Question 2. What problem has emerged in parts of London?"], [129.09, 132.29, "Q", "Question 3. What do the scientists recommend?"]]}, "ll1": {"src": "assets/audio/ll1.m4a", "dur": 196.5, "q": 125.54, "segs": [[0.0, 0.94, "", "Good morning."], [1.16, 6.26, "", "Today I want to talk about something all of you do, though probably not enough of: sleep."], [6.48, 13.26, "", "For a long time, scientists assumed that sleep was simply a period of rest, a time when the brain switched off."], [13.48, 15.57, "", "We now know that the opposite is true."], [15.79, 24.5, "", "During sleep, the brain is extremely busy, and one of its main tasks is sorting through the day's experiences and deciding what to keep."], [24.72, 37.43, "", "Brain scans show that during deep sleep, the hippocampus, a small region that holds new information for a short time, replays the events of the day and passes them on to the cortex for long-term storage."], [37.65, 40.23, "", "Let me describe an experiment from my own lab."], [40.45, 44.59, "", "We asked two groups of students to learn a list of word pairs in the evening."], [44.81, 46.88, "", "One group then slept for eight hours."], [47.1, 51.77, "", "The other group stayed awake and was tested the next morning after a night without sleep."], [51.99, 53.42, "", "The difference was striking."], [53.64, 56.99, "", "The sleep group remembered about forty percent more of the pairs."], [57.21, 61.16, "", "Frankly, I expected the tired group to catch up once they had rested."], [61.38, 67.78, "", "But when we tested both groups again a week later, after everyone had caught up on sleep, the gap had not closed."], [68.0, 73.59, "", "Those who missed sleep on the first night never recovered the memories they had failed to consolidate."], [73.81, 76.32, "", "So the lesson is not simply that sleep helps."], [76.54, 81.3, "", "It is that the night immediately after learning is a window that does not reopen."], [81.52, 91.51, "", "We have since repeated the study with more than three hundred students and with different kinds of material, from vocabulary to math problems, and the pattern holds every time."], [91.73, 94.75, "", "This has obvious implications for how you study."], [94.97, 104.0, "", "Pulling an all-nighter before an exam may let you cram facts into short-term memory, but it also prevents the brain from storing what you learned that day."], [104.22, 110.96, "", "A far better strategy is to study in the afternoon, review briefly before bed, and then sleep a full night."], [111.18, 112.27, "", "One more point."], [112.49, 115.84, "", "Many students tell me they will sleep when the exams are over."], [116.06, 120.69, "", "But our data suggest that what you lose during exam season does not come back."], [120.91, 124.02, "", "Treat sleep as part of studying, not as its opposite."], [125.54, 130.19, "Q", "Questions 1 to 4 are based on the recording you have just heard."], [131.39, 135.36, "Q", "Question 1. What did scientists once believe about sleep?"], [147.36, 151.48, "Q", "Question 2. What did the speaker's experiment find a week later?"], [163.48, 168.9, "Q", "Question 3. What does the speaker say about staying up all night before an exam?"], [180.9, 184.5, "Q", "Question 4. What is the speaker's advice to students?"]]}, "lc3": {"src": "assets/audio/lc3.m4a", "dur": 183.7, "q": 111.38, "segs": [[0.0, 2.05, "W", "Professor Hale, do you have a minute?"], [2.17, 6.8, "W", "I wanted to ask about the research assistant position you mentioned in class."], [7.27, 8.38, "M", "Of course, Jenny."], [8.5, 9.16, "M", "Come in."], [9.28, 10.58, "M", "I'm glad you're interested."], [10.7, 12.7, "M", "Tell me, what draws you to the project?"], [13.17, 21.94, "W", "Well, honestly, I've been reading about how cities manage storm water, and your work on green roofs seems like a practical way to deal with flooding."], [22.06, 26.48, "W", "I grew up in a town that flooded almost every spring, so it feels personal."], [26.95, 28.02, "M", "That's a good reason."], [28.14, 30.7, "M", "But I should be clear about what the job involves."], [30.82, 32.42, "M", "A lot of it is not glamorous."], [32.54, 40.45, "M", "You'd be climbing onto rooftops twice a week to collect water samples, and then spending hours in the lab running them through the equipment."], [40.92, 42.56, "W", "I actually don't mind that."], [42.68, 48.25, "W", "I worked in a water quality lab last summer, so I'm familiar with most of the testing procedures."], [48.72, 50.02, "M", "Oh, that changes things."], [50.14, 56.93, "M", "I was going to say the training would take a month, but if you already know the basics, you could start contributing right away."], [57.05, 58.22, "M", "What about your schedule?"], [58.34, 61.62, "M", "The sampling has to happen early in the morning, around six."], [62.09, 65.96, "W", "Six is early, but I can manage it on Mondays and Thursdays."], [66.08, 72.65, "W", "The only problem is that I have a statistics class at nine on Thursdays, so I'd need to be done by eight thirty."], [73.12, 74.55, "M", "That should work if you're efficient."], [74.67, 78.98, "M", "Now, the funding only covers ten hours a week, and the pay is modest."], [79.1, 81.04, "M", "Some students find that discouraging."], [81.51, 84.47, "W", "To be honest, the money isn't my main concern."], [84.59, 89.24, "W", "What I really want is to be listed as a co-author if the results get published."], [89.36, 90.41, "W", "Is that possible?"], [90.88, 95.89, "M", "It depends on how much you contribute to the analysis, not just the data collection."], [96.01, 100.36, "M", "But I've had undergraduates on papers before, so yes, it's realistic."], [100.83, 102.13, "W", "Then I'd like to apply."], [102.6, 103.14, "M", "Good."], [103.26, 109.91, "M", "Send me your lab report from last summer and a short statement by Friday, and I'll let you know early next week."], [111.38, 116.14, "Q", "Questions 1 to 4 are based on the conversation you have just heard."], [117.34, 121.65, "Q", "Question 1. Why is Jenny interested in the professor's project?"], [133.65, 138.94, "Q", "Question 2. What makes Jenny a stronger candidate than the professor expected?"], [150.94, 155.19, "Q", "Question 3. What scheduling difficulty does Jenny mention?"], [167.19, 171.71, "Q", "Question 4. What does Jenny care most about regarding the position?"]]}, "lc4": {"src": "assets/audio/lc4.m4a", "dur": 203.1, "q": 132.66, "segs": [[0.0, 1.96, "W", "Welcome back to the program."], [2.08, 13.88, "W", "My guest today is Daniel Reyes, whose new documentary about small family farms has just won a major award."], [14.0, 16.07, "W", "Daniel, congratulations."], [16.54, 17.35, "M", "Thank you."], [17.47, 19.9, "M", "It still feels a bit unreal, to be honest."], [20.37, 22.25, "W", "Let's start at the beginning."], [22.37, 24.42, "W", "What made you choose this subject?"], [24.54, 29.98, "W", "Farming isn't exactly a typical topic for a young filmmaker."], [30.45, 32.09, "M", "You know, that's exactly why."], [32.21, 36.24, "M", "Everyone my age was making films about cities and technology."], [36.36, 41.12, "M", "I kept thinking, who is telling the story of the people who actually grow our food?"], [41.24, 45.85, "M", "So I drove out to the countryside with a camera and started knocking on doors."], [46.32, 48.77, "W", "And how did the farmers react to that?"], [49.24, 50.39, "M", "Not well, at first."], [50.51, 55.01, "M", "Most of them assumed I was going to make them look foolish or old-fashioned."], [55.13, 58.74, "M", "One man told me to leave his property within thirty seconds."], [59.21, 61.07, "W", "So how did you win them over?"], [61.54, 62.71, "M", "I stopped filming."], [62.83, 65.07, "M", "For the first two months I just helped out."], [65.19, 68.2, "M", "I fed animals, repaired fences, got up at five."], [68.32, 72.73, "M", "Eventually they realized I was serious, and the cameras came out naturally."], [73.2, 75.87, "W", "The film took three years to complete."], [75.99, 78.76, "W", "Did you ever think about giving up?"], [79.23, 80.19, "M", "Many times."], [80.31, 83.81, "M", "Actually, the hardest moment wasn't about money or time."], [83.93, 89.63, "M", "It was when one of the families I had grown close to lost their farm to debt halfway through filming."], [89.75, 92.9, "M", "I wasn't sure I had the right to keep recording their pain."], [93.37, 94.59, "W", "But you did."], [95.06, 96.19, "M", "They asked me to."], [96.31, 100.24, "M", "They said if people didn't see what was happening, nothing would change."], [100.36, 102.04, "M", "That gave me the push to finish."], [102.51, 106.16, "W", "What do you hope audiences take away from the film?"], [106.63, 109.19, "M", "I'm not trying to make anyone feel guilty."], [109.31, 117.01, "M", "I'd just like people to think for a second about where their dinner comes from, and maybe buy from a local farm once in a while."], [117.48, 119.0, "W", "And what's next for you?"], [119.47, 124.54, "M", "I've been offered a big budget project in Hollywood, but I've decided to turn it down."], [124.66, 131.19, "M", "There are still stories in the countryside I haven't told, and I'd rather stay small and keep my independence."], [132.66, 137.42, "Q", "Questions 1 to 4 are based on the conversation you have just heard."], [138.62, 143.53, "Q", "Question 1. Why did Daniel decide to make a film about small farms?"], [155.53, 159.11, "Q", "Question 2. How did Daniel gain the farmers' trust?"], [171.11, 175.27, "Q", "Question 3. What was the most difficult moment during the project?"], [187.27, 191.09, "Q", "Question 4. What has Daniel decided about his future?"]]}, "lp2": {"src": "assets/audio/lp2.m4a", "dur": 164.4, "q": 110.23, "segs": [[0.0, 10.43, "", "Walk into any large supermarket and you will find dozens of kinds of toothpaste, hundreds of breakfast cereals, and an entire aisle of salad dressing."], [10.65, 19.44, "", "For decades, businesses assumed that offering more options was always better, because customers could find exactly what they wanted."], [19.66, 23.71, "", "Recent research suggests the picture is more complicated."], [23.93, 29.78, "", "In a well-known experiment, psychologists set up a tasting table in a grocery store."], [30.0, 34.33, "", "On some days the table displayed twenty-four varieties of jam."], [34.55, 36.92, "", "On other days it displayed only six."], [37.14, 41.92, "", "The larger display attracted more shoppers, who stopped to look and sample."], [42.14, 47.09, "", "But when the researchers counted actual purchases, the result was surprising."], [47.31, 54.15, "", "Shoppers who saw six jams were nearly ten times more likely to buy one than those who saw twenty-four."], [54.37, 60.37, "", "The explanation, researchers argue, is that too many options create a mental burden."], [60.59, 69.04, "", "Comparing every possibility takes effort, and the fear of making the wrong choice can be strong enough that people simply walk away."], [69.26, 77.04, "", "Even those who do buy often feel less satisfied afterward, because they keep wondering whether another option would have been better."], [77.26, 79.91, "", "Some companies have taken the lesson to heart."], [80.13, 88.88, "", "One consumer goods firm cut its range of shampoo from twenty-six varieties to fifteen and saw sales rise by ten percent."], [89.1, 91.91, "", "Of course, this does not mean choice is bad."], [92.13, 98.49, "", "People value having options, and a store with a single brand of everything would not do well either."], [98.71, 108.71, "", "The point is that variety has a cost as well as a benefit, and the best retailers are those who help customers choose rather than simply overwhelm them."], [110.23, 114.65, "Q", "Questions 1 to 3 are based on the passage you have just heard."], [115.85, 121.33, "Q", "Question 1. What did businesses traditionally believe about product variety?"], [133.33, 136.64, "Q", "Question 2. What did the jam experiment reveal?"], [148.64, 152.37, "Q", "Question 3. What does the speaker conclude about choice?"]]}, "lp3": {"src": "assets/audio/lp3.m4a", "dur": 162.4, "q": 106.14, "segs": [[0.0, 5.29, "", "When people think about protecting the ocean, they usually picture coral reefs or whales."], [5.51, 12.21, "", "Few give much thought to seagrass, the flowering plants that form underwater meadows in shallow coastal waters."], [12.43, 20.71, "", "Yet scientists are increasingly convinced that these quiet green fields may be among the most valuable ecosystems on the planet."], [20.93, 30.44, "", "Seagrass meadows cover less than one percent of the sea floor, but they are responsible for around ten percent of the carbon stored in ocean sediments each year."], [30.66, 41.43, "", "The plants pull carbon dioxide from the water as they grow, and when their leaves die, they sink into the mud, where the carbon can remain locked away for thousands of years."], [41.65, 47.46, "", "Acre for acre, a seagrass meadow absorbs carbon far faster than a tropical forest."], [47.68, 57.11, "", "The meadows also provide a nursery for young fish, filter pollutants from the water, and slow down waves, which protects coastlines from erosion."], [57.33, 61.55, "", "Despite these benefits, seagrass is disappearing at an alarming rate."], [61.77, 66.51, "", "Globally, an area the size of a football field is lost every thirty minutes."], [66.73, 75.75, "", "The main causes are pollution from farms and cities, which clouds the water and blocks sunlight, and damage from boat anchors and fishing equipment."], [75.97, 79.43, "", "The good news is that seagrass can recover if given a chance."], [79.65, 86.6, "", "In one bay on the eastern coast of the United States, volunteers scattered millions of seeds over two decades."], [86.82, 94.03, "", "The meadow has now expanded to cover more than three thousand hectares, and fish and shellfish that had vanished have returned."], [94.25, 104.62, "", "The project shows that restoration is possible, but researchers stress that it is far cheaper to protect the meadows that still exist than to replant those already lost."], [106.14, 110.56, "Q", "Questions 1 to 3 are based on the passage you have just heard."], [111.76, 116.81, "Q", "Question 1. Why do scientists consider seagrass meadows so valuable?"], [128.81, 133.1, "Q", "Question 2. What is one major reason for the loss of seagrass?"], [145.1, 150.37, "Q", "Question 3. What do researchers emphasize about seagrass restoration?"]]}, "lp4": {"src": "assets/audio/lp4.m4a", "dur": 176.1, "q": 105.9, "segs": [[0.0, 3.2, "", "Could working less actually make companies more productive?"], [3.42, 15.17, "", "That is the question behind a large experiment carried out in the United Kingdom, in which more than sixty companies and nearly three thousand employees switched to a four-day week for six months."], [15.39, 21.75, "", "Workers kept their full salaries but were expected to deliver the same output in eighty percent of the time."], [21.97, 32.34, "", "The organizers were careful to include a range of businesses, from marketing agencies and software firms to a fish and chip shop and a small manufacturing company."], [32.56, 37.59, "", "At the end of the trial, the results were more positive than many managers had predicted."], [37.81, 42.42, "", "Company revenue stayed roughly the same, and in some cases rose slightly."], [42.64, 49.98, "", "Staff reported lower levels of stress and burnout, and the number of employees leaving their jobs fell by more than half."], [50.2, 58.24, "", "Perhaps most tellingly, over ninety percent of the participating companies decided to keep the shorter week after the trial ended."], [58.46, 61.13, "", "How did they fit five days of work into four?"], [61.35, 63.85, "", "The most common answer was by cutting waste."], [64.07, 69.53, "", "Teams shortened or canceled meetings, reduced interruptions, and set clearer priorities."], [69.75, 77.11, "", "Several managers admitted they had not realized how much of the week was being spent on tasks that added little value."], [77.33, 79.63, "", "The trial did reveal some difficulties."], [79.85, 87.81, "", "Businesses that serve customers every day, such as shops and restaurants, had to arrange staff in shifts, which was harder to manage."], [88.03, 93.51, "", "A few employees also said that the shorter week made their working days feel more intense."], [93.73, 98.96, "", "Still, the organizers argue that the experiment challenges a long-held assumption."], [99.18, 104.38, "", "Time spent at a desk, they say, is a poor measure of how much work actually gets done."], [105.9, 110.34, "Q", "Questions 1 to 4 are based on the passage you have just heard."], [111.54, 115.72, "Q", "Question 1. What were employees in the trial required to do?"], [127.72, 131.5, "Q", "Question 2. What was the most striking outcome of the trial?"], [143.5, 148.13, "Q", "Question 3. How did most companies manage to reduce working time?"], [160.13, 164.07, "Q", "Question 4. Which type of business found the change hardest?"]]}, "ll2": {"src": "assets/audio/ll2.m4a", "dur": 197.9, "q": 126.91, "segs": [[0.0, 1.6, "", "Good afternoon, everyone."], [1.82, 4.91, "", "Before we begin, I'd like you to look at what's on your desk."], [5.13, 7.03, "", "Most of you have a laptop open."], [7.25, 9.43, "", "A few of you have a notebook and a pen."], [9.65, 16.26, "", "Today I want to talk about whether that choice matters, because the research suggests it matters more than you might think."], [16.48, 24.42, "", "Several years ago, two psychologists ran a series of studies comparing students who took notes by hand with students who typed."], [24.64, 28.29, "", "Both groups watched the same lectures and were tested afterward."], [28.51, 33.09, "", "On questions that asked for simple facts, the two groups performed about the same."], [33.31, 40.46, "", "But on questions that required understanding concepts and applying ideas, the handwriting group did significantly better."], [40.68, 41.77, "", "Why would that be?"], [41.99, 43.61, "", "The answer lies in speed."], [43.83, 46.71, "", "Most people can type much faster than they can write."], [46.93, 50.26, "", "That sounds like an advantage, but it turned out to be a trap."], [50.48, 56.85, "", "Because typing is fast, students tended to record the lecture almost word for word, like a transcript."], [57.07, 63.77, "", "Writing by hand is slow, so students were forced to listen, decide what mattered, and put it into their own words."], [63.99, 67.92, "", "That act of selecting and rephrasing is itself a form of learning."], [68.14, 70.74, "", "The researchers then tried something interesting."], [70.96, 76.68, "", "They told the laptop group explicitly not to copy word for word and to summarize instead."], [76.9, 80.63, "", "Even with that warning, most of them still produced near transcripts."], [80.85, 82.67, "", "The habit was simply too strong."], [82.89, 85.83, "", "Now, I am not telling you to throw away your computers."], [86.05, 94.92, "", "Typed notes are easier to search, share, and organize, and for some tasks, such as recording a long list of references, they are clearly better."], [95.14, 103.42, "", "There is also newer research suggesting that students who use a stylus to write on a tablet get similar benefits to those using paper."], [103.64, 106.88, "", "The key factor is not the technology but the process."], [107.1, 108.83, "", "So here is my suggestion."], [109.05, 114.9, "", "During lectures, write by hand, or at least force yourself to summarize rather than transcribe."], [115.12, 118.81, "", "Then, when you review, type up your notes in an organized form."], [119.03, 125.39, "", "You get the benefit of deep processing the first time and the benefit of searchable records the second time."], [126.91, 131.56, "Q", "Questions 1 to 4 are based on the recording you have just heard."], [132.76, 135.89, "Q", "Question 1. What is the lecture mainly about?"], [147.89, 153.2, "Q", "Question 2. On which type of question did handwriting students perform better?"], [165.2, 170.96, "Q", "Question 3. What happened when laptop users were told not to copy word for word?"], [182.96, 185.91, "Q", "Question 4. What does the speaker recommend?"]]}, "ll3": {"src": "assets/audio/ll3.m4a", "dur": 207.2, "q": 135.06, "segs": [[0.0, 4.89, "", "Today's topic is a puzzle that has fascinated business researchers for decades."], [5.11, 10.69, "", "Why do successful, well-managed companies so often fail when a new technology appears?"], [10.91, 20.28, "", "You might expect that a firm with the most money, the best engineers, and the most loyal customers would be in the strongest position to adopt whatever comes next."], [20.5, 21.8, "", "History says otherwise."], [22.02, 28.61, "", "Think about the companies that dominated film photography, or the firms that made the first mobile phones."], [28.83, 32.14, "", "Almost none of them led the industries that replaced them."], [32.36, 41.04, "", "One influential explanation comes from a professor at Harvard who studied the computer disk drive industry in the nineteen eighties and nineties."], [41.26, 46.51, "", "He found that the leading firms were actually very good at improving their existing products."], [46.73, 52.85, "", "They listened carefully to their biggest customers, who wanted drives that were faster and held more data."], [53.07, 59.45, "", "The problem was that the new technology, smaller drives, was at first worse on exactly those measures."], [59.67, 63.21, "", "It was slower, stored less, and cost more per unit of storage."], [63.43, 65.57, "", "The big customers had no interest in it."], [65.79, 68.75, "", "So the established firms, quite rationally, ignored it."], [68.97, 78.1, "", "Meanwhile, small startups sold the smaller drives to new customers, such as makers of portable computers, who valued size over capacity."], [78.32, 86.51, "", "As the new technology improved, it eventually became good enough for the mainstream market, and the big firms found they had been pushed aside."], [86.73, 88.38, "", "The lesson here is uncomfortable."], [88.6, 92.07, "", "The leading companies did not fail because they were badly run."], [92.29, 96.95, "", "They failed because they were well run, by the standards of their existing business."], [97.17, 107.9, "", "Listening to customers, investing where the profits are, and improving the core product are all sensible practices, and they are precisely what blinded these firms to the threat."], [108.12, 109.5, "", "So what can a company do?"], [109.72, 111.41, "", "The research suggests two things."], [111.63, 120.61, "", "First, firms should create small, separate units that are free to pursue new technologies even when those technologies look unprofitable at first."], [120.83, 127.49, "", "Second, managers should pay attention to the customers they do not have, not only the ones they already serve."], [127.71, 130.24, "", "The next big market rarely announces itself."], [130.46, 133.54, "", "It usually starts somewhere that looks too small to matter."], [135.06, 139.71, "Q", "Questions 1 to 4 are based on the recording you have just heard."], [140.91, 145.07, "Q", "Question 1. What puzzle does the speaker introduce at the beginning?"], [157.07, 162.04, "Q", "Question 2. Why did leading disk drive firms ignore the smaller drives?"], [174.04, 179.26, "Q", "Question 3. According to the speaker, why did the established companies fail?"], [191.26, 195.23, "Q", "Question 4. What does the speaker suggest companies should do?"]]}, "ll4": {"src": "assets/audio/ll4.m4a", "dur": 244.4, "q": 188.15, "segs": [[0.0, 2.07, "", "Let me start with a question."], [2.29, 8.11, "", "How many of you have ever handed in an assignment later than you planned?"], [8.33, 10.19, "", "I see a lot of hands."], [10.41, 11.73, "", "Don't feel bad."], [11.95, 22.81, "", "You are experiencing one of the most reliable findings in psychology, something researchers call the planning fallacy."], [23.03, 40.03, "", "The planning fallacy is our tendency to underestimate how long a task will take, even when we have done similar tasks before and know that they took longer than expected."], [40.25, 48.17, "", "In one classic study, students were asked to estimate when they would finish their senior thesis."], [48.39, 52.48, "", "The average prediction was about thirty-four days."], [52.7, 56.27, "", "The actual average was fifty-five days."], [56.49, 62.35, "", "Only about thirty percent finished by the date they had predicted."], [62.57, 69.12, "", "And remember, these were students who had been handing in late work for years."], [69.34, 73.61, "", "Their past experience did not seem to help them at all."], [73.83, 76.62, "", "This is not just a student problem."], [76.84, 83.22, "", "Large public projects show the same pattern on a much bigger scale."], [83.44, 100.13, "", "A review of several hundred transportation projects around the world found that nine out of ten went over budget, and the average cost overrun was around thirty percent."], [100.35, 105.38, "", "Opera houses, railways, software systems, you name it."], [105.6, 107.24, "", "Why does this happen?"], [107.46, 109.94, "", "Researchers point to two causes."], [110.16, 116.13, "", "The first is that when we plan, we imagine the task going smoothly."], [116.35, 128.68, "", "We picture ourselves working steadily, and we do not picture the illness, the broken computer, or the unexpected request from a friend."], [128.9, 133.3, "", "The second is that we treat each project as unique."], [133.52, 143.95, "", "We focus on the details of this particular task and ignore what happened with similar tasks in the past."], [144.17, 148.63, "", "The most effective solution is surprisingly simple."], [148.85, 157.08, "", "Instead of asking how long this task will take, ask how long tasks like this usually take."], [157.3, 160.48, "", "Researchers call this taking the outside view."], [160.7, 172.37, "", "In experiments, people who were prompted to recall how long similar past tasks took gave much more accurate estimates."], [172.59, 177.82, "", "So, before your next deadline, do not build a schedule from scratch."], [178.04, 186.63, "", "Look at your history, add the time you always seem to need, and start earlier than feels necessary."], [188.15, 192.7, "Q", "Questions 1 to 3 are based on the recording you have just heard."], [193.9, 198.59, "Q", "Question 1. What did the study of students writing a thesis find?"], [210.59, 215.39, "Q", "Question 2. What is one reason the speaker gives for the planning fallacy?"], [227.39, 232.36, "Q", "Question 3. What does the speaker advise for making better time estimates?"]]}, "ll5": {"src": "assets/audio/ll5.m4a", "dur": 204.9, "q": 148.47, "segs": [[0.0, 1.13, "", "Good morning."], [1.35, 7.69, "", "I want to begin today with two temperature readings taken on the same summer afternoon in the same city."], [7.91, 12.22, "", "One, from a park on the west side, read twenty-nine degrees Celsius."], [12.44, 18.0, "", "The other, from a parking lot less than two kilometers away, read thirty-eight degrees."], [18.22, 22.28, "", "Nine degrees of difference, within one city, at the same moment."], [22.5, 28.53, "", "This is what we call the urban heat island effect, and it is the focus of today's lecture."], [28.75, 33.19, "", "Cities are hotter than the surrounding countryside for several reasons."], [33.41, 38.96, "", "Asphalt and concrete absorb sunlight during the day and release it slowly at night."], [39.18, 40.67, "", "Buildings block wind."], [40.89, 44.18, "", "Cars and air conditioners produce heat of their own."], [44.4, 57.79, "", "And perhaps most importantly, cities have replaced vegetation with hard surfaces, removing the natural cooling that plants provide through shade and through the evaporation of water from their leaves."], [58.01, 61.45, "", "This matters because heat is not just uncomfortable."], [61.67, 63.14, "", "It is dangerous."], [63.36, 74.35, "", "During a severe heat wave in Europe some years ago, tens of thousands of people died, most of them elderly residents of apartments in dense urban neighborhoods."], [74.57, 80.22, "", "Studies afterward found that mortality was highest in the areas with the least tree cover."], [80.44, 82.19, "", "Which brings me to trees."], [82.41, 89.56, "", "A growing body of research shows that trees are among the most cost-effective tools a city has against heat."], [89.78, 95.13, "", "A single mature tree can lower the air temperature beneath it by several degrees."], [95.35, 109.62, "", "One study of a large American city estimated that increasing tree canopy by ten percent could reduce summer heat-related deaths by a measurable amount, at a fraction of the cost of other solutions."], [109.84, 112.38, "", "There is, however, a problem of fairness."], [112.6, 117.23, "", "In most cities, wealthy neighborhoods have far more trees than poor ones."], [117.45, 130.1, "", "One survey found that the richest districts had nearly twice the canopy cover of the poorest, which means the people with the fewest resources to cope with heat are also the ones most exposed to it."], [130.32, 136.0, "", "So when city governments plan tree planting, they should not simply spread trees evenly."], [136.22, 138.56, "", "They should start where the need is greatest."], [138.78, 146.95, "", "That means prioritizing the neighborhoods that are hottest, most densely built, and least able to afford air conditioning."], [148.47, 153.02, "Q", "Questions 1 to 3 are based on the recording you have just heard."], [154.22, 160.38, "Q", "Question 1. What is the main cause of urban heat islands that the speaker emphasizes?"], [172.38, 176.78, "Q", "Question 2. What did studies of the European heat wave reveal?"], [188.78, 192.87, "Q", "Question 3. What does the speaker recommend to city governments?"]]}, "ll6": {"src": "assets/audio/ll6.m4a", "dur": 217.6, "q": 147.61, "segs": [[0.0, 1.13, "", "Thank you for coming."], [1.35, 11.72, "", "Today I want to discuss a health risk that does not appear on any medical chart, yet according to recent research may be as harmful as smoking fifteen cigarettes a day."], [11.94, 13.62, "", "I am talking about loneliness."], [13.84, 16.11, "", "Let me first be clear about what I mean."], [16.33, 18.99, "", "Loneliness is not the same as being alone."], [19.21, 27.57, "", "Many people live alone and feel perfectly content, while others feel lonely in the middle of a crowded office or even within a marriage."], [27.79, 34.13, "", "Loneliness is the painful gap between the social connection we want and the connection we actually have."], [34.35, 36.59, "", "It is a feeling, not a situation."], [36.81, 43.06, "", "For a long time, doctors treated loneliness as a personal matter, something sad but not medical."], [43.28, 44.5, "", "That view has changed."], [44.72, 57.79, "", "A large analysis combining data from more than three hundred thousand people found that those with weak social ties had a roughly fifty percent higher risk of early death than those with strong ties."], [58.01, 62.84, "", "That effect was larger than the effect of obesity or physical inactivity."], [63.06, 71.33, "", "Other studies have linked chronic loneliness to heart disease, weakened immune function, and a faster decline in memory in old age."], [71.55, 74.31, "", "Why would a feeling affect the body so strongly?"], [74.53, 78.19, "", "One explanation is that loneliness acts as a stress signal."], [78.41, 86.48, "", "For our ancestors, being separated from the group was genuinely dangerous, so the brain learned to treat isolation as a threat."], [86.7, 96.0, "", "Chronic loneliness keeps the body in a constant state of alert, with raised levels of stress hormones that gradually damage the heart and blood vessels."], [96.22, 100.51, "", "It is tempting to assume that this is mainly a problem of the elderly."], [100.73, 111.01, "", "In fact, surveys in several countries find that young adults report the highest levels of loneliness of any age group, despite being the most connected online."], [111.23, 113.53, "", "Some governments have begun to respond."], [113.75, 123.03, "", "One country has appointed a minister responsible for loneliness, and several cities now fund programs that bring older and younger residents together."], [123.25, 124.73, "", "What can individuals do?"], [124.95, 128.15, "", "The research offers a modest but encouraging answer."], [128.37, 131.78, "", "The quality of relationships matters far more than the number."], [132.0, 137.57, "", "A few people you can truly rely on protect your health better than a long list of acquaintances."], [137.79, 146.09, "", "So my advice is not to be more social in general, but to invest in a small number of relationships, consistently and over time."], [147.61, 152.26, "Q", "Questions 1 to 4 are based on the recording you have just heard."], [153.46, 157.08, "Q", "Question 1. How does the speaker define loneliness?"], [169.08, 174.76, "Q", "Question 2. What did the large analysis of over three hundred thousand people show?"], [186.76, 190.6, "Q", "Question 3. What does the speaker say about young adults?"], [202.6, 205.63, "Q", "Question 4. What is the speaker's advice?"]]}, "lc5": {"src": "assets/audio/lc5.m4a", "dur": 232.4, "q": 162.28, "segs": [[0.0, 1.17, "M", "Good morning, Ms."], [1.29, 2.02, "M", "Carter."], [2.14, 3.35, "M", "Thanks for coming in."], [3.82, 4.96, "W", "Thank you."], [5.08, 10.9, "W", "I'm glad to finally meet you in person after our phone call last week."], [11.37, 12.24, "M", "Likewise."], [12.36, 15.39, "M", "So, you've applied for the event coordinator position."], [15.51, 19.4, "M", "Your resume says you've been working at a hotel for the past three years."], [19.52, 20.84, "M", "Why do you want to leave?"], [21.31, 27.96, "W", "I've learned a lot there, especially about handling guests when things go wrong."], [28.08, 35.02, "W", "But the hotel mostly hosts the same kind of business conferences over and over."], [35.14, 45.89, "W", "I'm looking for a role where I can plan events from the very first idea, not just manage the rooms and the catering."], [46.36, 47.11, "M", "I see."], [47.23, 48.74, "M", "Our events are quite varied."], [48.86, 54.07, "M", "One week it's a charity concert, the next it's a food festival for five thousand people."], [54.19, 58.99, "M", "Can you give me an example of a time you dealt with a serious problem under pressure?"], [59.46, 60.4, "W", "Sure."], [60.52, 67.24, "W", "Last spring, two hours before a wedding reception, the kitchen lost power."], [67.36, 68.98, "W", "The chef was panicking."], [69.1, 83.62, "W", "I called a restaurant nearby that we had worked with before, arranged for them to cook the main course, and had our own staff serve it as if nothing had happened."], [83.74, 86.22, "W", "Most of the guests never knew."], [86.69, 87.56, "M", "Impressive."], [87.68, 89.22, "M", "And how did the couple react?"], [89.69, 96.67, "W", "They actually sent us a thank you letter, and they've booked their anniversary dinner with us."], [97.14, 98.82, "M", "That's the kind of thinking we need."], [98.94, 105.53, "M", "Now, I should mention that this job involves a fair amount of travel, maybe one week in every month."], [105.65, 106.85, "M", "Would that be an issue?"], [107.32, 108.51, "W", "Not at all."], [108.63, 112.2, "W", "In fact, it's one of the things that attracted me."], [112.32, 115.2, "W", "My only concern is the weekends."], [115.32, 120.58, "W", "I understand most events happen on Saturdays and Sundays."], [121.05, 125.02, "M", "They do, but we give coordinators two weekdays off to make up for it."], [125.49, 126.79, "W", "That sounds fair."], [127.26, 129.08, "M", "Do you have any questions for me?"], [129.55, 130.55, "W", "Yes."], [130.67, 136.54, "W", "What would you say is the biggest challenge for someone new in this role?"], [137.01, 138.82, "M", "Honestly, it's learning to say no."], [138.94, 144.96, "M", "Clients always want more than their budget allows, and new coordinators tend to promise everything."], [145.08, 147.15, "M", "The best people are polite but firm."], [147.62, 149.58, "W", "That's really useful to know."], [149.7, 155.93, "W", "I'll admit that saying no to people is something I still need to work on."], [156.4, 157.93, "M", "I appreciate your honesty."], [158.05, 160.81, "M", "We'll be making a decision by the end of next week."], [162.28, 167.03, "Q", "Questions 1 to 4 are based on the conversation you have just heard."], [168.23, 172.07, "Q", "Question 1. Why does the woman want to leave her current job?"], [184.07, 188.06, "Q", "Question 2. What did the woman do when the kitchen lost power?"], [200.06, 204.16, "Q", "Question 3. What does the man say about working on weekends?"], [216.16, 220.36, "Q", "Question 4. What does the woman admit at the end of the interview?"]]}, "lc6": {"src": "assets/audio/lc6.m4a", "dur": 210.7, "q": 141.58, "segs": [[0.0, 3.07, "W", "Hi, I have an appointment with the study abroad office."], [3.19, 4.66, "W", "My name is Lucy Chen."], [5.13, 6.86, "M", "Hi Lucy, I'm Mark."], [6.98, 8.18, "M", "Come on in."], [8.3, 12.71, "M", "You said in your email that you're trying to decide between two programs?"], [13.18, 13.97, "W", "Yes."], [14.09, 18.06, "W", "One is a semester in Edinburgh, and the other is a full year in Seoul."], [18.18, 23.56, "W", "I'm majoring in international business, and both have courses that would count toward my degree."], [24.03, 25.78, "M", "Both are strong programs."], [25.9, 28.16, "M", "Let's start with the practical side."], [28.28, 30.13, "M", "Have you thought about the cost?"], [30.6, 31.93, "W", "That's my main worry."], [32.05, 36.7, "W", "The Seoul program lasts a whole year, so I assumed it would be much more expensive."], [37.17, 40.09, "M", "Actually, that's a common misunderstanding."], [40.21, 49.89, "M", "Living costs in Seoul are lower than in Edinburgh, and the Seoul program comes with a partial scholarship for students who take Korean language classes."], [50.01, 56.29, "M", "When you add it all up, the year in Seoul costs only slightly more than the semester in Edinburgh."], [56.76, 57.57, "W", "Really?"], [57.69, 58.9, "W", "I had no idea."], [59.02, 61.01, "W", "But I don't speak any Korean at all."], [61.48, 62.8, "M", "You wouldn't need to."], [62.92, 65.48, "M", "The business courses there are taught in English."], [65.6, 69.97, "M", "The language classes are an extra, and they start from the beginner level."], [70.09, 75.49, "M", "Many of our students say the language turned out to be the most valuable part of the year."], [75.96, 78.58, "W", "My other concern is graduating on time."], [78.7, 81.54, "W", "If I'm away for a whole year, will I fall behind?"], [82.01, 83.68, "M", "Let me check your record."], [83.8, 94.29, "M", "You've already completed most of your required courses, so as long as you take two approved business courses each semester abroad, you'll graduate with your class."], [94.76, 95.74, "W", "That's a relief."], [95.86, 97.23, "W", "What about internships?"], [97.35, 101.98, "W", "My parents keep telling me that an internship matters more than studying abroad."], [102.45, 104.75, "M", "Here's something your parents might like."], [104.87, 109.16, "M", "The Seoul program includes a summer placement with a local company."], [109.28, 114.46, "M", "Students work there for eight weeks, and some have even received job offers afterward."], [114.93, 117.11, "W", "That would definitely help me convince them."], [117.23, 119.34, "W", "Is there a deadline I should know about?"], [119.81, 120.58, "M", "Yes."], [120.7, 126.84, "M", "Applications for next fall close on March first, and you'll need two letters of recommendation."], [126.96, 132.3, "M", "I'd suggest asking your professors now, since they get very busy around that time."], [132.77, 133.56, "W", "OK."], [133.68, 135.49, "W", "I think I'm leaning toward Seoul."], [135.61, 140.11, "W", "I'll talk it over with my parents this weekend and then start on the application."], [141.58, 146.34, "Q", "Questions 1 to 4 are based on the conversation you have just heard."], [147.54, 150.99, "Q", "Question 1. What was Lucy's main worry at first?"], [162.99, 166.88, "Q", "Question 2. What does the man say about the program in Seoul?"], [178.88, 183.38, "Q", "Question 3. What must Lucy do in order to graduate on time?"], [195.38, 198.66, "Q", "Question 4. What will Lucy probably do next?"]]}, "lc7": {"src": "assets/audio/lc7.m4a", "dur": 187.2, "q": 116.52, "segs": [[0.0, 1.49, "M", "Hey, Emma, do you have a minute?"], [1.61, 4.3, "M", "There's something I've been meaning to talk to you about."], [4.77, 5.6, "W", "Sure, Josh."], [5.72, 6.41, "W", "What's up?"], [6.53, 7.61, "W", "You sound serious."], [8.08, 9.26, "M", "It's about the kitchen."], [9.38, 14.39, "M", "I don't want to make a big deal out of it, but the dishes have been piling up in the sink for days."], [14.51, 18.56, "M", "Last night I wanted to cook dinner and there wasn't a single clean pan."], [19.03, 19.57, "W", "Oh."], [19.69, 20.9, "W", "I know, I'm sorry."], [21.02, 25.72, "W", "I've had three exams this week and I've basically been living on instant noodles."], [25.84, 29.31, "W", "I kept telling myself I'd wash everything on the weekend."], [29.78, 31.92, "M", "I understand you're busy, but so am I."], [32.04, 33.4, "M", "And it's not just this week."], [33.52, 35.53, "M", "The same thing happened last month, too."], [36.0, 36.74, "W", "That's fair."], [36.86, 39.83, "W", "But can I bring something up as well, since we're talking?"], [40.3, 41.07, "M", "Of course."], [41.19, 41.93, "M", "Go ahead."], [42.4, 43.41, "W", "It's your friends."], [43.53, 47.09, "W", "They come over almost every night and stay until after midnight."], [47.21, 51.11, "W", "My room is right next to the living room, and I can hear every word."], [51.23, 54.11, "W", "I've had real trouble sleeping before my exams."], [54.58, 55.25, "M", "Really?"], [55.37, 57.09, "M", "Why didn't you say something earlier?"], [57.21, 58.96, "M", "I had no idea it was that loud."], [59.43, 61.16, "W", "I didn't want to seem unfriendly."], [61.28, 62.48, "W", "They're nice people."], [62.6, 64.66, "W", "I just need some quiet on weeknights."], [65.13, 66.52, "M", "OK, now I feel bad."], [66.64, 67.64, "M", "How about this?"], [67.76, 70.69, "M", "From Sunday to Thursday, my friends leave by ten."], [70.81, 73.67, "M", "On Friday and Saturday, we can be more flexible."], [74.14, 75.78, "W", "That would make a huge difference."], [75.9, 78.59, "W", "And for the dishes, what if we make a simple rule?"], [78.71, 80.63, "W", "Whoever cooks washes up the same day."], [80.75, 81.79, "W", "No exceptions."], [82.26, 83.33, "M", "Sounds good to me."], [83.45, 90.19, "M", "Maybe we could also put a chart on the fridge for the bigger chores, like cleaning the bathroom and taking out the trash."], [90.31, 91.7, "M", "We could switch every week."], [92.17, 93.08, "W", "I like that."], [93.2, 97.28, "W", "Honestly, I was worried this conversation would turn into a big fight."], [97.75, 98.56, "M", "Me too."], [98.68, 103.95, "M", "I almost sent you a text message instead, but I thought it was better to talk face to face."], [104.42, 105.46, "W", "I'm glad you did."], [105.58, 108.83, "W", "Actually, let me go and wash those pans right now."], [109.3, 110.47, "M", "I'll help you dry them."], [110.59, 115.05, "M", "And let's check in again at the end of the month to see how the new system is working."], [116.52, 121.28, "Q", "Questions 1 to 4 are based on the conversation you have just heard."], [122.48, 126.04, "Q", "Question 1. What problem does the man raise first?"], [138.04, 142.24, "Q", "Question 2. Why didn't the woman complain about the noise earlier?"], [154.24, 158.21, "Q", "Question 3. What do the speakers agree about the man's friends?"], [170.21, 175.16, "Q", "Question 4. How do the speakers probably feel at the end of the conversation?"]]}, "lc8": {"src": "assets/audio/lc8.m4a", "dur": 207.6, "q": 137.55, "segs": [[0.0, 4.25, "W", "Good afternoon, and welcome to Local Voices."], [4.37, 13.5, "W", "Today I'm joined by Sam Patel, who opened a board game cafe on Main Street two years ago."], [13.62, 15.6, "W", "Sam, thanks for being here."], [16.07, 17.29, "M", "Thanks for having me."], [17.76, 24.11, "W", "For listeners who haven't visited, what exactly is a board game cafe?"], [24.58, 35.48, "M", "Basically, it's a cafe where you pay a small table fee, about five dollars per person, and then you can play any of the four hundred games on our shelves for as long as you like."], [35.6, 38.31, "M", "We also serve coffee, sandwiches, and snacks."], [38.78, 42.67, "W", "Before this, you worked as an accountant, right?"], [42.79, 44.71, "W", "What made you change careers?"], [45.18, 46.71, "M", "Yes, for nearly ten years."], [46.83, 50.2, "M", "The job was stable, but I spent all day looking at screens."], [50.32, 56.17, "M", "On weekends my friends and I would play board games, and I noticed how differently people behaved."], [56.29, 59.3, "M", "They laughed, they argued, they actually looked at each other."], [59.42, 62.08, "M", "I thought, there must be other people who want that."], [62.55, 64.56, "W", "Was it hard to get started?"], [65.03, 65.69, "M", "Very."], [65.81, 70.78, "M", "The banks weren't interested in lending money to someone with no restaurant experience."], [70.9, 74.38, "M", "In the end I borrowed from my family and sold my car."], [74.5, 76.14, "M", "The first six months were tough."], [76.26, 78.69, "M", "Some days we had fewer than ten customers."], [79.16, 81.15, "W", "So what turned things around?"], [81.62, 82.47, "M", "Two things."], [82.59, 90.97, "M", "First, we hired what we call game guides, staff members who teach the rules so customers don't have to read a thick instruction booklet."], [91.09, 93.12, "M", "That made a big difference for beginners."], [93.24, 97.49, "M", "Second, local schools and companies started booking us for team events."], [97.61, 100.72, "M", "Now those bookings make up about a third of our income."], [101.19, 102.36, "W", "Interesting."], [102.48, 104.68, "W", "Who are your typical customers?"], [105.15, 106.69, "M", "That's what surprised me most."], [106.81, 113.34, "M", "I expected mainly college students, but we get families, retired couples, even people on first dates."], [113.46, 116.25, "M", "A board game takes the pressure off conversation."], [116.72, 118.49, "W", "What's next for the cafe?"], [118.96, 122.08, "M", "People keep asking me to open a second location."], [122.2, 124.86, "M", "But to be honest, I'd rather do one place well."], [124.98, 131.57, "M", "My plan is to expand into the empty shop next door and add a quiet room for longer strategy games."], [132.04, 136.08, "W", "Sam Patel, thank you so much, and good luck."], [137.55, 142.3, "Q", "Questions 1 to 4 are based on the conversation you have just heard."], [143.5, 147.64, "Q", "Question 1. Why did Sam give up his job as an accountant?"], [159.64, 163.29, "Q", "Question 2. How did Sam pay for opening the cafe?"], [175.29, 179.96, "Q", "Question 3. According to Sam, what helped turn his business around?"], [191.96, 195.57, "Q", "Question 4. What does Sam plan to do in the future?"]]}, "lp5": {"src": "assets/audio/lp5.m4a", "dur": 169.9, "q": 112.02, "segs": [[0.0, 3.16, "", "For most of history, nights on Earth were dark."], [3.38, 18.33, "", "Today, more than eighty percent of the world's population lives under skies polluted by artificial light, and scientists are discovering that the glow from our streets and buildings is causing serious problems for wildlife."], [18.85, 21.82, "", "Migrating birds are among the most affected."], [22.04, 26.5, "", "Many species travel at night and use the stars to find their way."], [26.72, 35.76, "", "When they fly over brightly lit cities, they become confused and circle buildings until they are exhausted, or they crash into windows."], [35.98, 45.11, "", "In one American city, volunteers collected more than a thousand dead birds beneath a single office tower over the course of one autumn."], [45.63, 47.25, "", "Insects suffer too."], [47.47, 55.92, "", "A streetlight can attract moths from hundreds of meters away, and many of them die from exhaustion or are eaten before morning."], [56.14, 60.69, "", "Because moths pollinate plants at night, this matters for plants as well."], [60.91, 72.23, "", "One European study found that fields near streetlights received about sixty percent fewer visits from nighttime pollinators, and the plants there produced less fruit."], [72.75, 79.09, "", "The good news is that light pollution is one of the easiest environmental problems to fix."], [79.31, 84.41, "", "Unlike plastic in the ocean, it disappears the moment we turn the lights off."], [84.63, 89.15, "", "Several cities now dim office towers during migration seasons."], [89.37, 101.15, "", "Others have replaced white streetlights with warmer amber lights, which attract far fewer insects, and fitted shields so that light points down at the road instead of up into the sky."], [101.67, 110.5, "", "Experts say individuals can help as well, by closing their curtains at night and switching off outdoor lights that are not really needed."], [112.02, 116.43, "Q", "Questions 1 to 3 are based on the passage you have just heard."], [117.63, 122.93, "Q", "Question 1. Why do migrating birds have trouble flying over cities at night?"], [134.93, 139.9, "Q", "Question 2. What did the European study find about plants near streetlights?"], [151.9, 157.89, "Q", "Question 3. Why does the speaker say light pollution is relatively easy to deal with?"]]}, "lp6": {"src": "assets/audio/lp6.m4a", "dur": 175.1, "q": 102.67, "segs": [[0.0, 4.65, "", "Have you ever noticed that it feels easier to spend money with a card than with cash?"], [4.87, 10.52, "", "Psychologists have a name for the uncomfortable feeling we get when we hand over money."], [10.74, 17.04, "", "They call it the pain of paying, and research suggests that the way we pay changes how strongly we feel it."], [17.56, 23.36, "", "In one experiment, students were asked how much they would offer for tickets to a sold out concert."], [23.58, 27.42, "", "Half were told they would have to pay in cash, and half by credit card."], [27.64, 30.99, "", "The card group offered, on average, about twice as much."], [31.21, 39.89, "", "Other studies have found that shoppers who pay by card tend to buy more items and are more likely to pick up unhealthy snacks at the checkout."], [40.41, 41.63, "", "Why does this happen?"], [41.85, 47.16, "", "When we count out bills, we see our money physically leaving us, and that loss feels real."], [47.38, 55.15, "", "A card, by contrast, separates the pleasure of buying from the pain of paying, especially when the bill arrives weeks later."], [55.37, 63.66, "", "Phone payments and one click online shopping make the separation even greater, because there is almost no effort involved at all."], [64.18, 65.89, "", "Businesses understand this well."], [66.11, 73.68, "", "That is why many hotels, theme parks, and cruise ships let guests pay with wristbands or room charges instead of money."], [73.9, 78.06, "", "Customers stop thinking about prices and simply enjoy themselves."], [78.58, 81.44, "", "This does not mean we should all go back to cash."], [81.66, 84.12, "", "But experts suggest a few simple habits."], [84.34, 87.3, "", "Check your spending every day, rather than once a month."], [87.52, 93.64, "", "Remove saved card details from shopping websites, so that each purchase takes a little more effort."], [93.86, 98.07, "", "And before buying something expensive, imagine paying for it in cash."], [98.29, 101.15, "", "If that feels painful, it may be a sign to wait."], [102.67, 107.1, "Q", "Questions 1 to 4 are based on the passage you have just heard."], [108.3, 112.23, "Q", "Question 1. What did the experiment with concert tickets show?"], [124.23, 129.9, "Q", "Question 2. According to the passage, why does paying by card feel less painful?"], [141.9, 147.75, "Q", "Question 3. Why do some hotels and theme parks use wristbands or room charges?"], [159.75, 163.12, "Q", "Question 4. Which habit do experts recommend?"]]}, "lp7": {"src": "assets/audio/lp7.m4a", "dur": 153.6, "q": 98.24, "segs": [[0.0, 4.42, "", "It is widely believed that children are better language learners than adults."], [4.64, 13.08, "", "Watch a family move to a new country, and within a year the children are chatting with the neighbors while their parents still struggle to order a meal."], [13.3, 16.76, "", "But researchers say the full picture is more complicated."], [17.28, 20.5, "", "In the early stages, adults actually learn faster."], [20.72, 30.96, "", "Studies comparing learners of different ages have found that in the first few months, adults and teenagers pick up grammar and vocabulary more quickly than young children."], [31.18, 39.42, "", "Adults can use their reading skills, memorize word lists, and understand explanations of grammar rules, while a six year old cannot."], [39.94, 45.16, "", "Where children have a clear advantage is in the long run, especially in pronunciation."], [45.38, 52.42, "", "People who start a language before the age of about ten are far more likely to end up sounding like native speakers."], [52.64, 57.93, "", "Those who start later often keep a noticeable accent, even after decades of use."], [58.45, 63.04, "", "However, part of the children's advantage may have little to do with their brains."], [63.26, 71.71, "", "Children who move abroad usually go to school, where they spend hours each day surrounded by the new language and are pushed to make friends."], [71.93, 79.07, "", "Adults, on the other hand, often work with people who share their first language and go home to speak it with their families."], [79.29, 82.64, "", "Children are also less embarrassed about making mistakes."], [83.16, 86.09, "", "For adult learners, then, the message is encouraging."], [86.31, 89.04, "", "Age is not the barrier that many people assume."], [89.26, 96.72, "", "What matters more is how much time you spend actually using the language, and your willingness to sound foolish while you do it."], [98.24, 102.66, "Q", "Questions 1 to 3 are based on the passage you have just heard."], [103.86, 108.43, "Q", "Question 1. What do studies show about the first few months of learning?"], [120.43, 125.4, "Q", "Question 2. In what area do early starters have a lasting advantage?"], [137.4, 141.6, "Q", "Question 3. What is the speaker's message to adult learners?"]]}, "lp8": {"src": "assets/audio/lp8.m4a", "dur": 168.1, "q": 98.57, "segs": [[0.0, 4.01, "", "For decades, coaches told athletes to stretch before exercise."], [4.23, 10.55, "", "Many of us still begin a run by reaching down to touch our toes and holding the position for thirty seconds."], [10.77, 15.69, "", "Yet sports scientists now say this familiar routine may do more harm than good."], [16.21, 23.77, "", "The kind of stretching most people do is called static stretching, in which you hold a muscle in a lengthened position without moving."], [23.99, 33.56, "", "A large review of more than one hundred studies found that holding a stretch for over a minute before exercise made muscles temporarily weaker and slower."], [33.78, 39.33, "", "Sprinters who stretched this way ran slightly slower times, and jumpers did not jump as high."], [39.55, 44.5, "", "The effect was small, but in competitive sport, small differences decide who wins."], [45.02, 46.28, "", "What about injuries?"], [46.5, 48.4, "", "Here the evidence is surprising."], [48.62, 54.48, "", "In one study of more than a thousand army recruits, half stretched before training and half did not."], [54.7, 59.53, "", "After twelve weeks, injury rates in the two groups were almost exactly the same."], [60.05, 61.54, "", "So what should we do instead?"], [61.76, 64.87, "", "Experts recommend what is called a dynamic warm up."], [65.09, 70.64, "", "This means moving the body through the motions of the activity, at a gradually increasing speed."], [70.86, 76.51, "", "Before a run, for example, you might walk briskly, then jog gently, then do some leg swings."], [76.73, 81.04, "", "This raises body temperature and prepares the muscles without weakening them."], [81.56, 84.19, "", "Static stretching is not useless, however."], [84.41, 91.49, "", "Done after exercise, or as a separate session, it is an effective way to improve flexibility over time."], [91.71, 93.86, "", "The point is simply that timing matters."], [94.08, 97.05, "", "Save the long stretches for when your workout is over."], [98.57, 103.01, "Q", "Questions 1 to 4 are based on the passage you have just heard."], [104.21, 108.64, "Q", "Question 1. What did the review of over one hundred studies find?"], [120.64, 124.23, "Q", "Question 2. What did the study of army recruits show?"], [136.23, 139.81, "Q", "Question 3. What does a dynamic warm up involve?"], [151.81, 156.12, "Q", "Question 4. What does the speaker suggest about static stretching?"]]}, "ll7": {"src": "assets/audio/ll7.m4a", "dur": 215.3, "q": 144.77, "segs": [[0.0, 1.19, "", "Good morning, everyone."], [1.41, 8.31, "", "Today I want to talk about something almost all of you did before this class started, and probably during it as well."], [8.53, 9.81, "", "I mean multitasking."], [10.03, 18.3, "", "Many students believe they can listen to a lecture, answer messages, and browse social media at the same time without missing anything."], [18.52, 20.81, "", "Cognitive science tells a different story."], [21.33, 24.21, "", "Let's start with what is actually happening in the brain."], [24.43, 29.48, "", "For most tasks that require attention, we cannot truly do two things at once."], [29.7, 34.05, "", "Instead, the brain switches rapidly between them, and each switch has a cost."], [34.27, 39.67, "", "You have to drop one set of rules, remember where you were in the other task, and start again."], [39.89, 41.77, "", "Researchers call this the switch cost."], [41.99, 45.7, "", "Individually, these costs are tiny, often less than a second."], [45.92, 48.99, "", "But when you switch dozens of times an hour, they add up."], [49.21, 55.12, "", "Some estimates suggest that heavy switching can reduce productive time by as much as forty percent."], [55.64, 57.48, "", "There is also a cost to accuracy."], [57.7, 63.2, "", "In one common type of experiment, participants sort numbers and letters according to a rule."], [63.42, 67.03, "", "When the rule stays the same, people are fast and make few errors."], [67.25, 73.41, "", "When they must change rules every few trials, both their speed and their accuracy drop noticeably."], [73.93, 76.94, "", "Now, here is the part many of you will find surprising."], [77.16, 84.84, "", "Researchers at one American university compared people who multitask heavily in daily life with people who rarely do."], [85.06, 90.41, "", "You might expect the heavy multitaskers to be better at it, since they get so much practice."], [90.63, 92.19, "", "In fact, they performed worse."], [92.41, 98.53, "", "They were more easily distracted by irrelevant information, and they were slower to switch between tasks."], [98.75, 106.77, "", "One explanation is that constant multitasking trains the brain to respond to every new input, even unimportant ones."], [107.29, 108.38, "", "There are exceptions."], [108.6, 116.22, "", "If one task is completely automatic, like walking, you can combine it with something else, such as talking, without much loss."], [116.44, 119.94, "", "The problem arises when both tasks require conscious thought."], [120.46, 121.55, "", "So what can you do?"], [121.77, 124.11, "", "My advice is to work in focused blocks."], [124.33, 132.52, "", "Choose a period, say twenty five minutes, during which you do just one thing, and put your phone in another room, not just face down on the desk."], [132.74, 135.58, "", "Then take a short break before starting the next block."], [135.8, 139.58, "", "You will likely find that you finish the same work in far less time."], [139.8, 143.25, "", "And yes, that includes listening to me for the next forty minutes."], [144.77, 149.42, "Q", "Questions 1 to 4 are based on the recording you have just heard."], [150.62, 153.76, "Q", "Question 1. What is the lecture mainly about?"], [165.76, 171.07, "Q", "Question 2. What happens when participants have to change rules frequently?"], [183.07, 187.45, "Q", "Question 3. What did the research on heavy multitaskers find?"], [199.45, 203.26, "Q", "Question 4. What does the speaker advise students to do?"]]}, "ll8": {"src": "assets/audio/ll8.m4a", "dur": 257.6, "q": 203.17, "segs": [[0.0, 13.08, "", "Today's topic in our behavioral economics series is one of the simplest and most powerful ideas in the field, the default option."], [13.3, 18.18, "", "A default is what happens if you make no active choice."], [18.4, 27.45, "", "And it turns out that defaults shape our decisions far more than traditional economics would predict."], [27.97, 39.02, "", "Traditional economic models assume that people weigh costs and benefits and pick the option that serves them best."], [39.24, 53.51, "", "Under that assumption, it should not matter much which option is selected in advance, because a rational person would simply switch if another option were better."], [53.73, 56.06, "", "Yet the evidence says otherwise."], [56.58, 58.9, "", "Consider retirement savings."], [59.12, 67.55, "", "At many companies, employees used to have to fill out a form to join the company savings plan."], [67.77, 71.5, "", "Participation rates were often below half."], [71.72, 86.8, "", "When some companies changed the rules so that new employees were enrolled automatically but could leave at any time, participation jumped to around ninety percent."], [87.02, 88.92, "", "Nothing else had changed."], [89.14, 93.49, "", "Not the money, not the benefits, only the default."], [94.01, 96.34, "", "We see the same pattern elsewhere."], [96.56, 109.53, "", "Countries where citizens are organ donors unless they choose not to be have far higher donor rates than countries where people must sign up."], [109.75, 123.11, "", "Even something as small as the default setting on office thermostats, set one degree lower in winter, reduced energy use without many complaints."], [123.63, 125.95, "", "Why are defaults so powerful?"], [126.17, 128.79, "", "Economists point to three reasons."], [129.01, 130.64, "", "The first is effort."], [130.86, 137.36, "", "Changing an option requires time and attention, so people put it off."], [137.58, 148.59, "", "The second is that people often see the default as a recommendation, assuming someone has chosen it for a good reason."], [148.81, 159.9, "", "The third is that we tend to fear losses more than we value gains, so giving up the default feels like losing something."], [160.42, 163.86, "", "Of course, this power can be misused."], [164.08, 175.98, "", "Some companies make free trials turn into paid subscriptions automatically, knowing that many customers will forget to cancel."], [176.2, 179.49, "", "So my message today has two parts."], [179.71, 190.76, "", "If you ever design systems, whether for a business or a government, choose defaults that genuinely serve people's interests."], [190.98, 198.85, "", "And as consumers, take a moment to examine the options that have already been chosen for you."], [199.07, 201.65, "", "Not choosing is still a choice."], [203.17, 207.72, "Q", "Questions 1 to 3 are based on the recording you have just heard."], [208.92, 212.05, "Q", "Question 1. What is the lecture mainly about?"], [224.05, 229.43, "Q", "Question 2. What happened when companies enrolled new employees automatically?"], [241.43, 245.61, "Q", "Question 3. What does the speaker advise consumers to do?"]]}, "ll9": {"src": "assets/audio/ll9.m4a", "dur": 217.7, "q": 147.98, "segs": [[0.0, 1.26, "", "Good afternoon."], [1.48, 10.48, "", "Walk across almost any university campus or city park, and you will notice narrow strips of worn grass cutting across the lawns."], [10.7, 14.22, "", "These informal trails are known as desire paths."], [14.44, 22.78, "", "They form when enough people decide that the official sidewalk does not take them where they want to go, or takes too long to get there."], [23.0, 30.81, "", "Today I would like to explain why planners have started to treat these paths not as damage, but as valuable information."], [31.33, 36.13, "", "For a long time, the standard response to desire paths was to fight them."], [36.35, 42.9, "", "Planners put up fences, planted bushes, or posted signs telling people to keep off the grass."], [43.12, 44.98, "", "These measures rarely worked."], [45.2, 48.87, "", "People simply found another route, or stepped over the fence."], [49.09, 59.82, "", "Studies of pedestrian behavior show that walkers will almost always choose the shortest route if it saves more than a few seconds, whatever the designer intended."], [60.34, 63.41, "", "Some designers have taken a very different approach."], [63.63, 75.43, "", "There is a story, repeated in many planning textbooks, about a university that put up its new buildings but deliberately left the grass between them without any paths for a whole year."], [75.65, 82.73, "", "At the end of the year, the planners looked at where the grass had been worn away and paved exactly those lines."], [82.95, 87.43, "", "The result was a network of walkways that students actually used."], [87.95, 91.21, "", "Today, technology makes this approach much easier."], [91.43, 99.13, "", "Planners can study anonymous location data from phones, or use cameras to track how people move through a square."], [99.35, 109.19, "", "In one European city, this kind of analysis revealed that most people crossing a large plaza avoided its center, because there was no shade."], [109.41, 114.87, "", "After trees were planted, movement patterns changed completely within a single summer."], [115.39, 118.46, "", "The broader lesson goes beyond grass and sidewalks."], [118.68, 125.76, "", "Desire paths remind us that people's behavior often reveals needs they would never mention in a survey."], [125.98, 129.59, "", "Good design begins with observation, not assumption."], [130.11, 136.32, "", "So, for your project this term, I want each group to choose a public space on or near campus."], [136.54, 146.46, "", "Spend at least three hours watching how people actually use it, and then propose one change based on what you see, not on what you think people should do."], [147.98, 152.63, "Q", "Questions 1 to 4 are based on the recording you have just heard."], [153.83, 157.2, "Q", "Question 1. What does the lecture mainly discuss?"], [169.2, 174.06, "Q", "Question 2. How did planners traditionally respond to desire paths?"], [186.06, 189.95, "Q", "Question 3. What did the university in the story do?"], [201.95, 205.72, "Q", "Question 4. What are students asked to do for their project?"]]}, "ll10": {"src": "assets/audio/ll10.m4a", "dur": 201.3, "q": 147.19, "segs": [[0.0, 5.31, "", "Today we are going to look at a question that has become central to communication studies."], [5.53, 11.06, "", "Why does false information travel so quickly, and what, if anything, can be done about it?"], [11.58, 13.13, "", "Let's begin with the evidence."], [13.35, 22.74, "", "A team of researchers analyzed more than one hundred thousand news stories shared on a major social media platform over a period of ten years."], [22.96, 28.15, "", "They found that false stories reached more people, and reached them faster, than true ones."], [28.37, 34.64, "", "In fact, true stories took about six times as long as false ones to reach the same number of people."], [35.16, 40.02, "", "You might assume that automated accounts, often called bots, were responsible."], [40.24, 44.85, "", "But when the researchers removed bot activity from the data, the pattern remained."], [45.07, 47.78, "", "Humans, not machines, were the main drivers."], [48.0, 50.13, "", "So why do people share false stories?"], [50.35, 56.05, "", "The researchers found that false stories tended to be more novel, more surprising than true ones."], [56.27, 60.04, "", "And they triggered stronger emotions, such as disgust and fear."], [60.26, 66.88, "", "We share things that surprise us, partly because passing on new information makes us look well informed."], [67.4, 68.85, "", "So how should we respond?"], [69.07, 74.7, "", "The traditional approach is fact checking, which means correcting false claims after they spread."], [74.92, 77.89, "", "Fact checks do help, but they have a basic weakness."], [78.11, 83.57, "", "They arrive late, and corrections usually reach far fewer people than the original story did."], [84.09, 89.61, "", "This has led researchers to explore an approach borrowed from medicine, known as prebunking."], [89.83, 91.77, "", "The idea works like a vaccine."], [91.99, 106.18, "", "Instead of correcting one particular falsehood, you expose people in advance to a weakened form of the techniques used to mislead them, such as fake experts, highly emotional language, or false choices between two extremes."], [106.4, 119.86, "", "In several experiments, people who watched short videos explaining these techniques, or played online games in which they created fake headlines themselves, became noticeably better at spotting misleading content later."], [120.08, 122.83, "", "And the effect held across different political views."], [123.35, 125.21, "", "Prebunking is no magic cure."], [125.43, 130.38, "", "The effect fades over a few weeks, much like some vaccines, and needs boosters."], [130.6, 138.15, "", "But it suggests that teaching people how manipulation works may be more effective than chasing every false claim one by one."], [138.67, 145.67, "", "For next week, please find one example of misleading content online and identify which technique it uses."], [147.19, 151.73, "Q", "Questions 1 to 3 are based on the recording you have just heard."], [152.93, 156.07, "Q", "Question 1. What is the lecture mainly about?"], [168.07, 173.32, "Q", "Question 2. According to the research, why were false stories shared more widely?"], [185.32, 189.28, "Q", "Question 3. What does the speaker conclude about prebunking?"]]}, "ll11": {"src": "assets/audio/ll11.m4a", "dur": 208.6, "q": 138.13, "segs": [[0.0, 0.85, "", "Good morning."], [1.07, 7.84, "", "Over the past few years, almost every university has started recording its lectures and posting them online."], [8.06, 9.12, "", "Students love it."], [9.34, 13.1, "", "In surveys, more than ninety percent say recordings are useful."], [13.32, 21.7, "", "Today I want to look at what research says about how recordings affect learning, because the answer is less straightforward than you might think."], [22.22, 23.46, "", "First, the benefits."], [23.68, 32.21, "", "Recordings are especially valuable for students whose first language is not English, who can pause and replay difficult explanations."], [32.43, 38.38, "", "They also help students with disabilities, students who work part time, and anyone who is sick."], [38.6, 45.03, "", "For these groups, recordings make education fairer, and that alone is a strong argument for keeping them."], [45.55, 50.17, "", "The concerns arise when recordings replace attendance rather than support it."], [50.39, 56.67, "", "One study at a large university followed how students used recordings over a full semester."], [56.89, 62.95, "", "Students who attended lectures and used recordings to review difficult parts got the highest grades."], [63.17, 67.84, "", "But students who skipped class and planned to watch later did significantly worse."], [68.06, 69.55, "", "Many of them never caught up."], [69.77, 77.9, "", "The recordings piled up, and in the week before the exam, some students tried to watch twenty hours of lectures, often at double speed."], [78.42, 79.91, "", "Why does this hurt learning?"], [80.13, 81.86, "", "Cramming is part of the answer."], [82.08, 90.44, "", "We know from decades of research that spreading study over time leads to much better long term memory than packing it into a few days."], [90.66, 92.41, "", "Another factor is attention."], [92.63, 98.86, "", "When watching at home, students are far more likely to be interrupted by their phones or by other people."], [99.38, 101.83, "", "So what should universities and students do?"], [102.05, 108.03, "", "Removing recordings would harm the very students who need them most, so that is not the solution."], [108.25, 115.86, "", "Instead, some universities now release recordings with short quizzes built in, which encourage students to watch actively."], [116.08, 122.14, "", "Others keep recordings online for only a few weeks to discourage last minute viewing marathons."], [122.66, 125.03, "", "As for you, my recommendation is simple."], [125.25, 129.62, "", "Treat recordings as a tool for review, not a replacement for being here."], [129.84, 136.61, "", "If you really must miss a lecture, watch the recording within the same week, and take notes just as you would in class."], [138.13, 142.78, "Q", "Questions 1 to 4 are based on the recording you have just heard."], [143.98, 147.11, "Q", "Question 1. What is the lecture mainly about?"], [159.11, 164.4, "Q", "Question 2. Which students does the speaker say benefit greatly from recordings?"], [176.4, 181.63, "Q", "Question 3. What happened to students who skipped class and planned to watch later?"], [193.63, 196.57, "Q", "Question 4. What does the speaker recommend?"]]}, "ll12": {"src": "assets/audio/ll12.m4a", "dur": 196.6, "q": 142.99, "segs": [[0.0, 1.09, "", "Good afternoon."], [1.31, 9.86, "", "Today's lecture deals with a public health tool that has become increasingly popular, and increasingly controversial, over the past decade."], [10.08, 12.62, "", "I am talking about taxes on sugary drinks."], [13.14, 16.15, "", "The reasoning behind these taxes is fairly simple."], [16.37, 26.42, "", "Sugary drinks are one of the largest sources of added sugar in many people's diets, and they are strongly linked to obesity, type two diabetes, and tooth decay."], [26.64, 30.93, "", "Unlike most foods, these drinks provide almost no nutritional value."], [31.15, 36.31, "", "So if higher prices reduce consumption, the public health benefits could be considerable."], [36.83, 44.17, "", "More than fifty countries and cities have now introduced such taxes, which gives us a good deal of real world evidence."], [44.39, 55.03, "", "A review of studies from several countries found that a tax which raised prices by about ten percent reduced purchases of sugary drinks by roughly the same amount."], [55.25, 60.5, "", "In one major American city, sales of taxed drinks fell by more than a third within a year."], [61.02, 64.37, "", "One of the most interesting cases is the United Kingdom."], [64.59, 74.79, "", "Rather than taxing all sugary drinks equally, the government set different rates depending on how much sugar a drink contained, and it announced the plan two years in advance."], [75.01, 80.3, "", "Many companies responded by changing their recipes before the tax even began."], [80.52, 87.96, "", "As a result, the amount of sugar sold in soft drinks dropped substantially, even though total drink sales barely changed."], [88.18, 93.22, "", "In other words, the tax worked mainly by changing the products, not the customers."], [93.74, 95.96, "", "Critics raise reasonable objections."], [96.18, 100.27, "", "These taxes take a larger share of income from poorer households."], [100.49, 105.51, "", "And in some places, people simply drove to neighboring towns to buy cheaper drinks."], [105.73, 118.89, "", "Supporters reply that poorer communities also suffer most from diet related disease, so they stand to gain the most, especially if the money raised is spent on things like school sports or free drinking water."], [119.41, 120.86, "", "So what can we conclude?"], [121.08, 124.07, "", "A sugar tax on its own will not solve obesity."], [124.29, 133.48, "", "But the evidence suggests it works best when it is designed to encourage healthier products, and when the money it raises is visibly returned to the community."], [133.7, 141.47, "", "Policy makers should treat it as one part of a broader strategy that also includes health education and clearer food labels."], [142.99, 147.53, "Q", "Questions 1 to 3 are based on the recording you have just heard."], [148.73, 151.87, "Q", "Question 1. What is the lecture mainly about?"], [163.87, 168.28, "Q", "Question 2. What was special about the tax in the United Kingdom?"], [180.28, 184.57, "Q", "Question 3. What does the speaker suggest policy makers do?"]]}};
